// Deterministic world and combat simulation. No DOM or rendering dependencies.
import { moveCircle, steerAround, lineClear, indexObstacles, queryObstacles, obstacleCylinder } from './spatial.js';
import { landmarkSupports, houseFoundation } from './architecture-grounding.js';
import { findPath } from './navigation.js';
import { WEAPONS, SENA, EAST_CAMP, SUPPLY_ID, crossingText } from './content.js';
import { segmentCylinder, segmentTerrain } from './spatial.js';
import { captureRuntime, restoreRuntime } from './runtime-state.js';
import { createWoodland } from './woodland.js';
import { WIND_SHRINE, WIND_BELLS, ROAD_CACHE, createResidents, createBells, restoreBells, tickVillage, startForge, reportForge, interactShrine, forgeText, residentActive, useRoadCache } from './village.js';
import { WORLD_BOUNDS, SALT_JOURNEY, SALT_TARGETS, saltObstacles } from './world-regions.js';
import { createExpedition, restoreExpedition, applyExpeditionWorld, tickExpedition, expeditionQuest, interactExpedition } from './expedition.js';
import { createGatherings, restoreGatherings, tickGatherings } from './gatherings.js';
import { VAULT_SLICES, availableVaultTargets, claimVaultMemory, createVaultProgress, inVaultFootprint, restoreVaultProgress, tickVaultSlices, vaultAt, vaultByWarden, vaultObstacles } from './vault-slices.js';
export const WORLD_SEED = 87123;
export const SAVE_VERSION = 1;
export const TAU = Math.PI * 2;
export const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
export const distance = (a, b) => Math.hypot(a.x - b.x, a.z - b.z);
export const angleDelta = (a, b) => Math.atan2(Math.sin(a - b), Math.cos(a - b));
export function random(seed) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
export const PLACES = [
  { id:'haven', name:'風待ちの集落', en:'WINDFALL HAVEN', x:0, z:86, type:'camp' },
  { id:'grove', name:'琥珀の森', en:'AMBER GROVE', x:-104, z:2, type:'beacon' },
  { id:'flood', name:'沈黙の水殿', en:'THE DROWNED SANCTUM', x:106, z:-83, type:'beacon' },
  { id:'ruins', name:'星読みの廃塔', en:'ASTRAL WATCH', x:-48, z:-167, type:'beacon' },
  { id:'crown', name:'灰冠の門', en:'THE CINDER CROWN', x:4, z:-247, type:'boss' },
];
export const KEEPER = {id:'keeper',x:7,z:80,type:'npc',name:'灯守ミラと話す'};
export function heightAt(x, z) {
  let h = Math.sin(x * .023) * 5 + Math.cos(z * .021) * 4 + Math.sin((x + z) * .045) * 2 + Math.sin(x * .081) * Math.cos(z * .066) * .8;
  h += Math.max(0, Math.abs(x) - 190) * .26;
  h += Math.max(0, -z - 190) * .14;
  for (const p of PLACES) { const d = Math.hypot(x-p.x,z-p.z); if(d<24) { const level = p.type==='boss'?12:p.id==='ruins'?8:p.id==='flood'?1:3; h = h * Math.min(1,d/24) + level*(1-Math.min(1,d/24)); } }
