}
export const riverX = z => 166 + Math.sin(z*.017)*23;
export const BRIDGES=[-120,25].map(z=>{const x=riverX(z);let top=-Infinity;for(let dx=-14;dx<=14;dx+=2)top=Math.max(top,heightAt(x+dx,z));return{x,z,top:top+1.1};});
