    const facing=Math.abs(angleDelta(Math.atan2(target.x-enemy.x,target.z-enemy.z),enemy.angle));
    return distance(enemy,target)<range&&(enemy.radial||facing<1.5)&&(!enemy.radial||target.grounded)&&this.canStrike(enemy,target);
  }
  atSafeFire(){return !this.player.dead&&!this.threatened()&&PLACES.some(s=>this.lit.includes(s.id)&&distance(this.player,s)<8);}
  actionIdle(){const p=this.player;return !p.dead&&p.grounded&&['attack','dodge','parry','healTimer'].every(key=>p[key]<=0);}
  canCraft(){return this.actionIdle()&&!this.threatened();}
  canUpgrade(){return this.atSafeFire()&&this.actionIdle();}
  threatened(point=this.player,radius=18){return this.enemies.some(e=>!e.dead&&e.state!=='sealed'&&!(e.type==='boss'&&this.lit.length<4)&&distance(e,point)<radius)||this.projectiles.some(a=>a.owner!=='player'&&a.life>0&&distance(a,point)<12);}
  weaponStats(){return WEAPONS[this.player.weaponType]||WEAPONS.sword;}
  damageAmount(){return (26+this.player.weapon*8+(this.player.level-1)*2)*this.weaponStats().damage;}
  unlockWeapon(id){if(!WEAPONS[id]||this.weapons.includes(id))return;this.weapons.push(id);this.notify(`${WEAPONS[id].name}を手に入れた — 旅の記録で装備`);this.emit('save');}
  equipWeapon(id){const p=this.player;if(p.dead||!this.weapons.includes(id)||!WEAPONS[id]||p.attack>0||p.dodge>0||p.parry>0||p.healTimer>0)return false;p.weaponType=id;p.comboWindow=0;p.combo=0;this.clearActionBuffer();this.emit('save');return true;}
  xpNeeded(){return 60+this.player.level*35;}
  reward(ash,xp){const p=this.player;p.ash+=ash;p.xp+=xp;while(p.xp>=this.xpNeeded()){p.xp-=this.xpNeeded();p.level++;p.maxHp+=12;p.hp=p.maxHp;this.notify(`巡礼者 Lv.${p.level} — 生命力が増した`);this.emit('level');}}
  move(dx,dz) {
